55	    data->srcB = static_cast<uint32x4_t *>(aligned_alloc(64, ARM0102_KREG_SELECT_COUNT * sizeof(uint32x4_t)));
56	    data->expected = static_cast<uint32x4_t *>(aligned_alloc(64, ARM0102_KREG_SELECT_COUNT * sizeof(uint32x4_t)));
