     * into a safe finite range via the framework RNG (keeps auto-seed) */
    for (int i = 0; i < ARM0102_FMA_F32_COUNT; i++) {
        float *pa = reinterpret_cast<float *>(&data->srcA[i]);
        float *pb = reinterpret_cast<float *>(&data->srcB[i]);
