            case 2: data->expected[i] = vnegq_f32(vfmsq_f32(vnegq_f32(data->srcC[i]), data->srcA[i], data->srcB[i])); break;
            case 3: data->expected[i] = vnegq_f32(vfmaq_f32(vnegq_f32(data->srcC[i]), data->srcA[i], data->srcB[i])); break;
