            float32x4_t a = load_vec(&data->srcA[i]);   /* ldr q — source 1 */
            float32x4_t b = load_vec(&data->srcB[i]);   /* ldr q — source 2 */
            float32x4_t c = load_vec(&data->srcC[i]);   /* ldr q — addend */
