                case 1: res = vfmsq_f32(c, a, b); break;   /*  c - a*b  */
                case 2: res = vnegq_f32(vfmsq_f32(vnegq_f32(c), a, b)); break; /* -c + a*b */
                case 3: res = vnegq_f32(vfmaq_f32(vnegq_f32(c), a, b)); break; /* -c - a*b */
