1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0.
5	 *
6	 * @test @b arm0102_kreg_mask_sve
7	 * @parblock
8	 * SVE port of arm0102_kreg_mask (SDC trigger-format variant of kreg7/8:
9	 * 2-source vector loads + rotating compare-mask expansion
10	 * eq/gt/eq-u/tst + back-to-back store→reload→store amplifier).
11	 * The SVE version keeps the verified core-179 trigger recipe structure
12	 * but moves the data path to SVE: asm-guaranteed ldr z for the two source
13	 * loads, predicate compares (svcmpeq/svcmpgt) + svsel for the mask
14	 * expansion (the real SVE equivalent of the kreg semantics), and
15	 * back-to-back str z → ldr z → str z as the amplifier.
16	 * Golden precomputed in init on the same SVE units; memcmp in cold path.
17	 * @endparblock
18	 */
19	
20	#include "sandstone.h"
21	#include <cstdint>
22	#include <cstring>
23	#include <cstdlib>
24	
25	#if defined(__aarch64__)
26	#include <arm_sve.h>
27	#include <sys/auxv.h>
28	
29	#ifndef HWCAP_SVE
30	#define HWCAP_SVE (1 << 22)
31	#endif
32	#endif
33	
34	#define ARM0102_KREG_MASK_SVE_COUNT 1024   /* elements per buffer (uint32) */
35	
36	struct Arm0102KregMaskSveData {
37	    uint32_t *srcA;
38	    uint32_t *srcB;
39	    uint32_t *expected;
40	};
41	
42	#if defined(__aarch64__)
43	
44	/* 4-lane (16B) 语义的存/取 —— 与子块谓词 pg4 严格一致。
45	 * 注意不能用 svptrue_b32(): VL=256 时它是 8 lane/32B, 会越界写
46	 * 4 元素子块后面的内存 (851 次循环后堆元数据被砸穿 → double free,
47	 * 批次 1 调试时抓到的 bug)。 */
48	#define KREG_SVE_SUBLANES 4
49	
50	static inline void store_vec_sve(void *addr, svuint32_t val) {
51	    svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)KREG_SVE_SUBLANES);
52	    svst1_u32(pg, static_cast<uint32_t *>(addr), val);
53	}
54	
55	static inline svuint32_t load_vec_sve(const void *addr) {
56	    svuint32_t res;
57	    /* asm 保证的加载 (core-179 配方要求, 与原版 ldr q 对应);
58	     * SVE ldr z 按 VL 全宽载, 后续所有计算/存储都用 pg4 截断 */
59	    __asm__ volatile ("ldr %0, [%1]" : "=w"(res) : "r"(addr) : "memory");
60	    return res;
61	}
62	
63	/* 旋转比较掩码扩展: i%4 → eq/gt(signed)/eq-u/tst —— 谓词 + svsel (真 kreg 语义) */
64	static inline svuint32_t kreg_expand_rotating(svbool_t pg, svuint32_t a, svuint32_t b, int i) {
65	    switch (i % 4) {
66	        case 0: {  /* eq (signed reinterpret) */
67	            svint32_t sa = svreinterpret_s32_u32(a), sb = svreinterpret_s32_u32(b);
68	            svbool_t p = svcmpeq_s32(pg, sa, sb);
69	            return svsel_u32(p, svdup_u32(0xFFFFFFFFu), svdup_u32(0));
70	        }
