72	            svint32_t sa = svreinterpret_s32_u32(a), sb = svreinterpret_s32_u32(b);
73	            svbool_t p = svcmpgt_s32(pg, sa, sb);
74	            return svsel_u32(p, svdup_u32(0xFFFFFFFFu), svdup_u32(0));
